  return rows.length?`<div class="studio-table-scroll${scrollClass?' '+esc(scrollClass):''}"${scrollLabel?' tabindex="0" role="region" aria-label="'+esc(scrollLabel)+'"':''}><table class="studio-table${className?' '+esc(className):''}"><thead><tr>${heads.map((h,index)=>`<th scope="col"${columnClass(index)}>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(cells=>`<tr>${cells.map((cell,index)=>`<td${columnClass(index)}>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<p class="empty">${esc(empty)}</p>`;
