  if(simulationMarketScope(saved).portfolio){const targets=record.targets,allocations=list(record.allocations);return row('판단',esc(decision.action))+row('모의 실행',esc(decision.execution))+(targets?row('현금 목표 비중',percent(targets.cashWeight))+table(['종목','목표 비중','실행'],list(targets.targets).map(target=>{const a=allocations.find(v=>v.instrumentId===target.instrumentId);return [esc(fillAsset(target,saved).symbol),percent(target.targetWeight),esc(a?({FILLED:'모의 체결',BLOCKED:'주문 차단',NO_ORDER_REQUIRED:'목표 유지'})[a.status]||a.status:'추가 주문 없음')];}),'선정된 종목이 없습니다.'):'')+(allocations.some(a=>a.reason)?helpTooltip('종목별 실행 사유',allocations.filter(a=>a.reason).map(a=>fillAsset(a,saved).symbol+' · '+a.reason).join(' / '),{id:'simulation-portfolio-execution-help'}):'');}
