  const distribution=hasDistribution?'<section class="simulation-decision-section"><h3>행동 선택 확률 '+helpTooltip('행동 선택 확률',quant?'저장된 가격 지표와 기준모델의 점수를 변환한 매수·유지·매도 분포입니다. 투자 수익이 날 확률과 구분해 읽습니다.':'JEV가 반환한 매수·유지·매도의 선택 분포입니다. 실제 수익률과 매도 승률은 실험 보고서에서 확인합니다.',{id:'simulation-decision-distribution-help'})+'</h3><dl class="simulation-decision-probabilities">'+[['buy','매수'],['hold','유지'],['sell','매도']].map(([key,label])=>'<div'+((record.action||stored.action)===key?' class="selected"':'')+'><dt>'+label+'</dt><dd>'+percent(probabilities[key])+'</dd></div>').join('')+'</dl></section>':'';
  const target=record.targetWeight??stored.targetWeight,allocation=(finite(stored.currentWeight)?row('판단 전 보유 비중',percent(stored.currentWeight)):'')+(finite(target)?row('목표 보유 비중',percent(target)):'');
