    const mindOptions=minds().filter(m=>!practice||!eventMind(m.id)).map(m=>'<option value="'+esc(m.id)+'"'+(m.id===d.mindId?' selected':'')+'>'+esc(m.name)+'</option>').join('');
    const modeOptions=(capabilities?.graphMode?.supported||d.mode==='GRAPH_CANONICAL'?'<option value="GRAPH_CANONICAL"'+(d.mode==='GRAPH_CANONICAL'?' selected':'')+'>마인드 전략</option>':'')+
      (market.portfolio||market.sessionRule?'':'<option value="MECHANICAL"'+(d.mode==='MECHANICAL'?' selected':'')+'>기준 퀀트 전략 · BTC 9장</option><option value="JEV_RETROSPECTIVE"'+(d.mode==='JEV_RETROSPECTIVE'?' selected':'')+'>마인드 · JEV</option>');
    const modeField=practice
      ?'<div class="field"><span>실행 방식</span><strong>기준 퀀트 전략 · BTC 9장</strong><input type="hidden" name="mode" value="MECHANICAL"></div>'
      :'<div class="field"><span><label for="simulation-execution-mode">실행 방식</label> '+helpTooltip('실험 실행 방식',modeHelp,{id:'simulation-mode-help'})+'</span><select id="simulation-execution-mode" name="mode"'+(d.sourceSimulationId?' disabled':'')+'>'+modeOptions+'</select></div>';
    const step=setupStep(),stepper='<nav class="lab-stepper" aria-label="백테스트 준비">'+[['strategy','전략 선택'],['period','기간 선택'],['review','실행 검토']].map(([id,label],i)=>'<button type="button" data-simulation-action="setup-step" data-simulation-id="'+id+'" aria-current="'+(step===id?'step':'false')+'"><span>'+(i+1)+'</span>'+label+'</button>').join('')+'</nav>';
