  function start(){if(started)return;started=true;if(typeof document!=='undefined'){lab.start();learning.start();collection.start();document.addEventListener('click',click);document.addEventListener('submit',submit);document.addEventListener('change',change);document.addEventListener('input',input);document.addEventListener('close',dialogClosed,true);document.addEventListener('close',pendingReadClosed,true);document.addEventListener('click',pendingReadClosed,true);document.addEventListener('cancel',pendingReadClosed,true);document.addEventListener('toggle',disclosureChanged,true);document.addEventListener('invalid',revealInvalidField,true);}}
